alter table public.inventory_reservations add constraint inventory_reservation_branch_fk foreign key(organization_id,branch_id) references public.branches(organization_id,id), add constraint inventory_reservation_warehouse_fk foreign key(organization_id,warehouse_id) references public.warehouses(organization_id,id);
alter table public.stock_transfers add constraint stock_transfer_source_branch_fk foreign key(organization_id,source_branch_id) references public.branches(organization_id,id), add constraint stock_transfer_destination_branch_fk foreign key(organization_id,destination_branch_id) references public.branches(organization_id,id), add constraint stock_transfer_source_warehouse_fk foreign key(organization_id,source_warehouse_id) references public.warehouses(organization_id,id), add constraint stock_transfer_destination_warehouse_fk foreign key(organization_id,destination_warehouse_id) references public.warehouses(organization_id,id);
alter table public.stock_count_sessions add constraint stock_count_branch_fk foreign key(organization_id,branch_id) references public.branches(organization_id,id), add constraint stock_count_warehouse_fk foreign key(organization_id,warehouse_id) references public.warehouses(organization_id,id);
alter table public.inventory_reorder_overrides add constraint reorder_override_branch_fk foreign key(organization_id,branch_id) references public.branches(organization_id,id), add constraint reorder_override_warehouse_fk foreign key(organization_id,warehouse_id) references public.warehouses(organization_id,id), add constraint reorder_override_location_fk foreign key(organization_id,storage_location_id) references public.storage_locations(organization_id,id);
